import { findManifest, getFoundryConfigInfo } from "@foundryvtt/utils"
import console from "console"
import * as fse from "fs-extra"
import path from "path"
import process from "process"
import yargs from "yargs"
import { hideBin } from "yargs/helpers"

/********************/
/*       LINK       */
/********************/

/**
 * Link dist directory to first existing Foundry User Data folder
 * @returns: Promise<void>
 */
export async function link(done: () => void) {
  const foundryManifestInfo = await findManifest()
  if (!foundryManifestInfo) return done()
  const foundryManifest = await foundryManifestInfo.manifest()
  const foundryConfig = await getFoundryConfigInfo()
  if (!foundryManifest || !foundryConfig) return done()

  const linkDirectories = await Promise.all(
    foundryConfig.resolvedDataPath.map(async (dataPath: string) => {
      const baseUrl = await foundryManifestInfo.baseUrl()
      return path.join(dataPath, "Data", baseUrl!)
    }),
  )

  const argv = yargs(hideBin(process.argv)).options({
    clean: { type: "boolean", default: false },
  }).argv as { clean: boolean }
  const clean = argv.clean

  for (const linkDirectory of linkDirectories) {
    if (clean) {
      console.log(`Removing build in ${linkDirectory}.`)
      await fse.remove(linkDirectory)
    } else if (!(await fse.exists(linkDirectory))) {
      console.log(`Linking dist to ${linkDirectory}.`)
      await fse.ensureDir("dist")
      await fse.ensureDir(path.resolve(linkDirectory, ".."))
      await fse.symlink(path.resolve("dist"), linkDirectory)
    } else {
      console.log(`Skipped linking to ${linkDirectory}, as it already exists.`)
    }
  }
}
